-- S1 data types (6.1 data type): each case creates a scratch table, writes, reads and drops it
-- @s01_6_1_char_n_padding
DROP TABLE IF EXISTS t92_w1_c01; CREATE TABLE t92_w1_c01 (id INTEGER, c CHARACTER(5), PRIMARY KEY (id)); INSERT INTO t92_w1_c01 VALUES (1, 'ab'); SELECT id, c, CHAR_LENGTH(c), c || '|' FROM t92_w1_c01; DROP TABLE t92_w1_c01;
-- @s01_6_1_char_n_comparison_pad
DROP TABLE IF EXISTS t92_w1_c02; CREATE TABLE t92_w1_c02 (id INTEGER, c CHAR(5), PRIMARY KEY (id)); INSERT INTO t92_w1_c02 VALUES (1, 'ab'); SELECT id FROM t92_w1_c02 WHERE c = 'ab'; SELECT id FROM t92_w1_c02 WHERE c = 'ab   '; DROP TABLE t92_w1_c02;
-- @s01_6_1_char_n_too_long
DROP TABLE IF EXISTS t92_w1_c03; CREATE TABLE t92_w1_c03 (id INTEGER, c CHAR(3), PRIMARY KEY (id)); INSERT INTO t92_w1_c03 VALUES (1, 'abcdef'); SELECT * FROM t92_w1_c03; DROP TABLE t92_w1_c03;
-- @s01_6_1_char_n_too_long_trailing_spaces
DROP TABLE IF EXISTS t92_w1_c04; CREATE TABLE t92_w1_c04 (id INTEGER, c CHAR(3), PRIMARY KEY (id)); INSERT INTO t92_w1_c04 VALUES (1, 'ab    '); SELECT id, c || '|' FROM t92_w1_c04; DROP TABLE t92_w1_c04;
-- @s01_6_1_char_default_length_1
DROP TABLE IF EXISTS t92_w1_c05; CREATE TABLE t92_w1_c05 (id INTEGER, c CHAR, PRIMARY KEY (id)); INSERT INTO t92_w1_c05 VALUES (1, 'xy'); SELECT * FROM t92_w1_c05; DROP TABLE t92_w1_c05;
-- @s01_6_1_varchar_n_too_long
DROP TABLE IF EXISTS t92_w1_c06; CREATE TABLE t92_w1_c06 (id INTEGER, v VARCHAR(3), PRIMARY KEY (id)); INSERT INTO t92_w1_c06 VALUES (1, 'abcdef'); SELECT * FROM t92_w1_c06; DROP TABLE t92_w1_c06;
-- @s01_6_1_char_pk_padding
DROP TABLE IF EXISTS t92_w1_c07; CREATE TABLE t92_w1_c07 (k CHAR(4), v INTEGER, PRIMARY KEY (k)); INSERT INTO t92_w1_c07 VALUES ('a', 1); SELECT v FROM t92_w1_c07 WHERE k = 'a'; SELECT v FROM t92_w1_c07 WHERE k = 'a   '; DROP TABLE t92_w1_c07;
-- @s01_6_1_numeric_scale_rounding
DROP TABLE IF EXISTS t92_w1_c08; CREATE TABLE t92_w1_c08 (id INTEGER, n NUMERIC(5,2), PRIMARY KEY (id)); INSERT INTO t92_w1_c08 VALUES (1, 1.005); INSERT INTO t92_w1_c08 VALUES (2, 2.5); INSERT INTO t92_w1_c08 VALUES (3, 123.456); SELECT * FROM t92_w1_c08; DROP TABLE t92_w1_c08;
-- @s01_6_1_numeric_precision_overflow
DROP TABLE IF EXISTS t92_w1_c09; CREATE TABLE t92_w1_c09 (id INTEGER, n NUMERIC(5,2), PRIMARY KEY (id)); INSERT INTO t92_w1_c09 VALUES (1, 12345.6); SELECT * FROM t92_w1_c09; DROP TABLE t92_w1_c09;
-- @s01_6_1_decimal_exact_sum
DROP TABLE IF EXISTS t92_w1_c10; CREATE TABLE t92_w1_c10 (id INTEGER, d DECIMAL(10,2), PRIMARY KEY (id)); INSERT INTO t92_w1_c10 VALUES (1, 0.10); INSERT INTO t92_w1_c10 VALUES (2, 0.20); INSERT INTO t92_w1_c10 VALUES (3, 0.30); SELECT SUM(d), SUM(d) = 0.60 FROM t92_w1_c10; DROP TABLE t92_w1_c10;
-- @s01_6_1_decimal_exact_equality
DROP TABLE IF EXISTS t92_w1_c11; CREATE TABLE t92_w1_c11 (id INTEGER, d DECIMAL(10,2), PRIMARY KEY (id)); INSERT INTO t92_w1_c11 VALUES (1, 0.10); INSERT INTO t92_w1_c11 VALUES (2, 0.20); SELECT id FROM t92_w1_c11 WHERE d * 3 = 0.30 OR d + 0.10 = 0.30; DROP TABLE t92_w1_c11;
-- @s01_6_1_decimal_large_exact
DROP TABLE IF EXISTS t92_w1_c12; CREATE TABLE t92_w1_c12 (id INTEGER, d DECIMAL(20,0), PRIMARY KEY (id)); INSERT INTO t92_w1_c12 VALUES (1, 12345678901234567890); SELECT d, d + 1 FROM t92_w1_c12; DROP TABLE t92_w1_c12;
-- @s01_6_1_decimal_money_total
DROP TABLE IF EXISTS t92_w1_c13; CREATE TABLE t92_w1_c13 (id INTEGER, price DECIMAL(9,2), qty INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w1_c13 VALUES (1, 19.99, 3); INSERT INTO t92_w1_c13 VALUES (2, 0.07, 10); INSERT INTO t92_w1_c13 VALUES (3, 1234567.89, 1); SELECT SUM(price * qty) FROM t92_w1_c13; DROP TABLE t92_w1_c13;
-- @s01_6_1_decimal_division_scale
DROP TABLE IF EXISTS t92_w1_c14; CREATE TABLE t92_w1_c14 (id INTEGER, d DECIMAL(10,2), PRIMARY KEY (id)); INSERT INTO t92_w1_c14 VALUES (1, 10.00); SELECT d / 3 FROM t92_w1_c14; DROP TABLE t92_w1_c14;
-- @s01_6_1_numeric_as_pk
DROP TABLE IF EXISTS t92_w1_c15; CREATE TABLE t92_w1_c15 (k NUMERIC(10,2), v INTEGER, PRIMARY KEY (k)); INSERT INTO t92_w1_c15 VALUES (1.10, 1); INSERT INTO t92_w1_c15 VALUES (1.1, 2); SELECT * FROM t92_w1_c15; DROP TABLE t92_w1_c15;
-- @s01_6_1_smallint_range
DROP TABLE IF EXISTS t92_w1_c16; CREATE TABLE t92_w1_c16 (id INTEGER, s SMALLINT, PRIMARY KEY (id)); INSERT INTO t92_w1_c16 VALUES (1, 40000); SELECT * FROM t92_w1_c16; DROP TABLE t92_w1_c16;
-- @s01_6_1_integer_range
DROP TABLE IF EXISTS t92_w1_c17; CREATE TABLE t92_w1_c17 (id INTEGER, i INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w1_c17 VALUES (1, 2147483648); SELECT * FROM t92_w1_c17; DROP TABLE t92_w1_c17;
-- @s01_6_1_integer_insert_decimal_rounds
DROP TABLE IF EXISTS t92_w1_c18; CREATE TABLE t92_w1_c18 (id INTEGER, i INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w1_c18 VALUES (1, 2.5); INSERT INTO t92_w1_c18 VALUES (2, 3.7); SELECT * FROM t92_w1_c18; DROP TABLE t92_w1_c18;
-- @s01_6_1_real
DROP TABLE IF EXISTS t92_w1_c19; CREATE TABLE t92_w1_c19 (id INTEGER, r REAL, PRIMARY KEY (id)); INSERT INTO t92_w1_c19 VALUES (1, 0.1); INSERT INTO t92_w1_c19 VALUES (2, 16777217); SELECT * FROM t92_w1_c19; DROP TABLE t92_w1_c19;
-- @s01_6_1_float_p_small_is_real
DROP TABLE IF EXISTS t92_w1_c20; CREATE TABLE t92_w1_c20 (id INTEGER, f FLOAT(10), PRIMARY KEY (id)); INSERT INTO t92_w1_c20 VALUES (1, 0.1); INSERT INTO t92_w1_c20 VALUES (2, 16777217); SELECT * FROM t92_w1_c20; DROP TABLE t92_w1_c20;
-- @s01_6_1_float_no_p
DROP TABLE IF EXISTS t92_w1_c21; CREATE TABLE t92_w1_c21 (id INTEGER, f FLOAT, PRIMARY KEY (id)); INSERT INTO t92_w1_c21 VALUES (1, 0.1); SELECT * FROM t92_w1_c21; DROP TABLE t92_w1_c21;
-- @s01_6_1_double_precision
DROP TABLE IF EXISTS t92_w1_c22; CREATE TABLE t92_w1_c22 (id INTEGER, d DOUBLE PRECISION, PRIMARY KEY (id)); INSERT INTO t92_w1_c22 VALUES (1, 0.1); INSERT INTO t92_w1_c22 VALUES (2, 1E300); SELECT d, d * 10 FROM t92_w1_c22; DROP TABLE t92_w1_c22;
-- @s01_6_1_int_keyword_synonym
DROP TABLE IF EXISTS t92_w1_c23; CREATE TABLE t92_w1_c23 (id INT, d DEC(5,1), PRIMARY KEY (id)); INSERT INTO t92_w1_c23 VALUES (1, 1.25); SELECT * FROM t92_w1_c23; DROP TABLE t92_w1_c23;
-- @s01_6_1_insert_string_into_int
DROP TABLE IF EXISTS t92_w1_c24; CREATE TABLE t92_w1_c24 (id INTEGER, i INTEGER, PRIMARY KEY (id)); INSERT INTO t92_w1_c24 VALUES (1, 'x'); SELECT * FROM t92_w1_c24; DROP TABLE t92_w1_c24;
-- @s01_6_1_insert_int_into_char
DROP TABLE IF EXISTS t92_w1_c25; CREATE TABLE t92_w1_c25 (id INTEGER, c CHAR(5), PRIMARY KEY (id)); INSERT INTO t92_w1_c25 VALUES (1, 42); SELECT * FROM t92_w1_c25; DROP TABLE t92_w1_c25;
-- @s01_6_1_describe_column_types
DROP TABLE IF EXISTS t92_w1_c26; CREATE TABLE t92_w1_c26 (id INTEGER, c CHAR(5), v VARCHAR(7), n NUMERIC(6,2), s SMALLINT, r REAL, f FLOAT(10), PRIMARY KEY (id)); SELECT column_name, data_type, character_maximum_length, numeric_precision, numeric_scale FROM information_schema.columns WHERE table_name = 't92_w1_c26' ORDER BY ordinal_position; DROP TABLE t92_w1_c26;
